        },
        {
            "dimension": "CORRECTNESS",
            "severity": "HIGH",
            "location": "src/refund.ts:22-26",
            "finding": "\"`refundOrder`\" refunds \"`order.subtotal`\" (the amount before the discount), so a discounted order is refunded more than the customer paid (\"`order.total`\", which the webhook checks the payment against)."
        },
        {
            "dimension": "CORRECTNESS",
            "severity": "HIGH",
            "location": "src/admin.ts:30-41",
